class LspClient:
    def __init__(self, binary):
        self.proc = subprocess.Popen(
            [binary, "--stdio"],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        self.id = 0

    def request(self, method, params):
        self.id += 1
        msg = json.dumps({"jsonrpc": "2.0", "id": self.id, "method": method, "params": params})
        content = f"Content-Length: {len(msg)}\r\n\r\n{msg}"
        try:
            self.proc.stdin.write(content.encode())
            self.proc.stdin.flush()
            return self._read_response(self.id)
        except (BrokenPipeError, Exception):
            return None

    def notify(self, method, params):
        msg = json.dumps({"jsonrpc": "2.0", "method": method, "params": params})
        content = f"Content-Length: {len(msg)}\r\n\r\n{msg}"
        try:
            self.proc.stdin.write(content.encode())
            self.proc.stdin.flush()
        except BrokenPipeError:
            pass

    def _read_response(self, expected_id, timeout=30):
        deadline = time.time() + timeout
        while time.time() < deadline:
            header = b""
            while b"\r\n\r\n" not in header:
                byte = self.proc.stdout.read(1)
                if not byte:
                    return None
                header += byte

            content_length = 0
            for line in header.decode().split("\r\n"):
                if line.startswith("Content-Length:"):
                    content_length = int(line.split(":")[1].strip())

            body = self.proc.stdout.read(content_length)
            msg = json.loads(body)
            if "id" not in msg:
                continue
            if msg["id"] == expected_id:
                return msg.get("result")
        return None

    def initialize(self, root_uri):
        return self.request("initialize", {
            "processId": os.getpid(),
            "rootUri": root_uri,
            "capabilities": {
                "textDocument": {
                    "hover": {"contentFormat": ["markdown", "plaintext"]},
                    "completion": {"completionItem": {"snippetSupport": False}},
                    "synchronization": {"didSave": True},
                    "documentSymbol": {"hierarchicalDocumentSymbolSupport": True},
                    "semanticTokens": {"requests": {"full": True}},
                    "callHierarchy": {"dynamicRegistration": False},
                }
            },
        })

    def shutdown(self):
        try:
            self.request("shutdown", None)
            self.notify("exit", None)
            self.proc.wait(timeout=5)
        except Exception:
            self.proc.kill()


